619	func TestConcurrentSubmitConflict(t *testing.T) {
620		dir := t.TempDir()
621		receive := testBase
622		r1 := hb("n1", 1, receive.Add(-time.Minute), "1.0", 100, 0)
623		r2 := hb("n1", 1, receive.Add(-time.Minute), "2.0", 100, 0)
624	
625		var mu sync.Mutex
626		successes := 0
627		conflicts := 0
628		var errs []error
629		var wg sync.WaitGroup
630		for i := 0; i < 20; i++ {
631			wg.Add(1)
632			go func(i int) {
633				defer wg.Done()
634				store, err := OpenStore(dir)
635				if err != nil {
636					mu.Lock()
637					errs = append(errs, err)
638					mu.Unlock()
639					return
640				}
641				r := r1
642				if i%2 == 1 {
643					r = r2
644				}
645				_, _, err = store.Submit([]Heartbeat{r}, receive)
646				mu.Lock()
647				if err == nil {
648					successes++
649				} else if strings.Contains(err.Error(), "conflict") {
650					conflicts++
651				} else {
652					errs = append(errs, err)
653				}
654				mu.Unlock()
655			}(i)
656		}
657		wg.Wait()
658		if len(errs) != 0 {
659			t.Fatalf("unexpected errors: %v", errs)
660		}
661		// All 10 submissions of the winning variant succeed (1 new + 9
662		// duplicates); all 10 of the losing variant hit the conflict.
663		if successes != 10 {
664			t.Errorf("successes=%d, want 10", successes)
665		}
666		if conflicts != 10 {
667			t.Errorf("conflicts=%d, want 10", conflicts)
668		}
669		// The stored record is one of the two, intact.
670		store, err := OpenStore(dir)
671		if err != nil {
672			t.Fatal(err)
673		}
674		hist, err := store.History("n1")
675		if err != nil {
676			t.Fatal(err)
677		}
678		if len(hist) != 1 || (hist[0].Version != "1.0" && hist[0].Version != "2.0") {
679			t.Errorf("stored record invalid: %+v", hist)
680		}
681	}
