	if err := os.WriteFile(store.nodePath("n1"), []byte(`{bad`), 0o644); err != nil {
		t.Fatal(err)
	}
	_, _, err = store.Submit([]Heartbeat{hb("n1", 2, receive.Add(-time.Minute), "1.0", 101, 0)}, receive)
