func TestValidateHeartbeatErrorMessage(t *testing.T) {
	cases := []struct {
		hb  Heartbeat
		want string
	}{
		{hb("", 1, testBase, "1.0", 1, 0), "node"},
		{hb("n", 0, testBase, "1.0", 1, 0), "seq"},
		{hb("n", 1, testBase, "", 1, 0), "version"},
		{hb("n", 1, testBase, "1.0", -1, 0), "height"},
		{hb("n", 1, testBase, "1.0", 1, -1), "missed"},
