1	// Command edgefleet is the 验证者与边缘节点机群管理平台 entry point.
2	package main
3	
4	import (
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"time"
10	
11		"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
12	)
13	
14	func main() {
15		command := "demo"
16		if len(os.Args) > 1 {
17			command = os.Args[1]
18		}
19		switch command {
20		case "demo":
21			runDemo()
22		case "version":
23			fmt.Println("edgefleet 0.1.0")
24		case "heartbeat":
25			runHeartbeat(os.Args[2:])
26		case "help", "-h", "--help":
27			usage()
28		default:
29			fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
30			usage()
31			os.Exit(2)
32		}
33	}
34	
35	func usage() {
36		fmt.Println("usage: edgefleet [demo|version|heartbeat|help]")
37		fmt.Println()
38		fmt.Println("commands:")
39		fmt.Println("  demo       run the built-in evaluation demo")
40		fmt.Println("  version    print version")
41		fmt.Println("  heartbeat  receive, store and query real heartbeats")
42		fmt.Println("  help       show this help")
43		fmt.Println()
44		fmt.Println("run 'edgefleet heartbeat --help' for heartbeat input format and storage location")
45	}
46	
47	// defaultDataDir resolves the data directory: --data-dir flag, then the
48	// EDGEFLEET_DATA_DIR environment variable, then ~/.edgefleet.
49	func defaultDataDir() string {
50		if d := os.Getenv("EDGEFLEET_DATA_DIR"); d != "" {
51			return d
52		}
53		home, err := os.UserHomeDir()
54		if err != nil {
55			return ".edgefleet"
56		}
57		return home + "/.edgefleet"
58	}
59	
60	// die prints an error to stderr and exits with status 1.
61	func die(format string, args ...any) {
62		fmt.Fprintf(os.Stderr, "error: "+format+"\n", args...)
63		os.Exit(1)
64	}
65	
66	// parseTime parses an RFC3339 time flag, defaulting to now when empty.
67	func parseTimeFlag(value, flagName string) time.Time {
68		if value == "" {
69			return time.Now()
70		}
71		t, err := time.Parse(time.RFC3339, value)
72		if err != nil {
73			die("invalid %s %q: must be RFC3339 with timezone (e.g. 2026-10-01T12:00:00+08:00)", flagName, value)
74		}
75		return t
76	}
77	
78	func runHeartbeat(args []string) {
79		if len(args) == 0 {
80			heartbeatUsage()
81			return
82		}
83		switch args[0] {
84		case "submit":
85			cmdSubmit(args[1:])
86		case "health":
87			cmdHealth(args[1:])
88		case "history":
89			cmdHistory(args[1:])
90		case "help", "-h", "--help":
91			heartbeatUsage()
92		default:
93			fmt.Fprintf(os.Stderr, "unknown heartbeat command %q\n", args[0])
94			heartbeatUsage()
95			os.Exit(2)
96		}
97	}
98	
99	func heartbeatUsage() {
100		fmt.Println("usage: edgefleet heartbeat <submit|health|history> [flags]")
101		fmt.Println()
102		fmt.Println("commands:")
103		fmt.Println("  submit   receive heartbeats from stdin as a JSON array")
104		fmt.Println("  health   query node health from its latest telemetry")
105		fmt.Println("  history  list all heartbeats for a node, ascending by seq")
106		fmt.Println()
107		fmt.Println("input format (submit):")
108		fmt.Println("  A JSON array of heartbeat objects; every field is required.")
109		fmt.Println("    node          string   node id (non-empty)")
110		fmt.Println("    seq           integer  sequence number (> 0)")
111		fmt.Println("    collected_at  string   RFC3339 with timezone, e.g. 2026-10-01T12:00:00+08:00")
112		fmt.Println("                           must not be later than the receive time")
113		fmt.Println("    version       string   version (non-empty)")
114		fmt.Println("    height        integer  block height (>= 0)")
115		fmt.Println("    missed        integer  cumulative missed duties (>= 0)")
116		fmt.Println()
117		fmt.Println("  example:")
118		fmt.Println(`    [{"node":"val-eu-1","seq":7,"collected_at":"2026-10-01T11:59:00+08:00",`)
119		fmt.Println(`      "version":"1.26.0","height":12345,"missed":0}]`)
120		fmt.Println()
121		fmt.Println("flags:")
122		fmt.Println("  submit   --data-dir DIR        data directory (default: $EDGEFLEET_DATA_DIR or ~/.edgefleet)")
123		fmt.Println("           --receive-time TIME   receive time, RFC3339 (default: now)")
124		fmt.Println("  health   --node ID             node id (required)")
125		fmt.Println("           --expected-version V  expected version (required)")
126		fmt.Println("           --tolerated-misses N  tolerated missed duties, >= 0 (required)")
127		fmt.Println("           --missed-since-seq S  seq of a saved heartbeat used as the")
128		fmt.Println("                                missed-duty baseline (optional, > 0)")
129		fmt.Println("           --at TIME             query time, RFC3339 (default: now)")
130		fmt.Println("           --data-dir DIR        data directory")
131		fmt.Println()
132		fmt.Println("  Without --missed-since-seq the missed-duty alarm uses the cumulative")
133		fmt.Println("  missed count of the latest heartbeat (missed in the output). With it,")
134		fmt.Println("  the alarm counts only missed duties newly recorded between the baseline")
135		fmt.Println("  heartbeat seq S and the latest one; a count strictly greater than")
136		fmt.Println("  --tolerated-misses alarms, equality does not. The output then shows the")
137		fmt.Println("  baseline seq, the baseline cumulative count and the new count. If the")
138		fmt.Println("  cumulative counter decreased between the baseline and the latest record")
139		fmt.Println("  (e.g. after a node reset), the new count is shown as 无法判断 and a")
140		fmt.Println("  累计漏签数回退 finding is reported; the baseline must name an existing")
141		fmt.Println("  saved seq, otherwise the command fails.")
142		fmt.Println()
143		fmt.Println("  history  --node ID             node id (required)")
144		fmt.Println("           --data-dir DIR        data directory")
145		fmt.Println()
146		fmt.Println("data storage:")
147		fmt.Println("  <data-dir>/nodes/<hex-node-id>.json, one file per node.")
148		fmt.Println("  Writes are atomic and the directory is locked for concurrent access.")
149		fmt.Println("  Corrupt data is refused, never silently cleared.")
150	}
151	
152	func newFlagSet(name string) *flag.FlagSet {
153		fs := flag.NewFlagSet(name, flag.ContinueOnError)
154		fs.SetOutput(os.Stderr)
155		fs.Usage = func() { heartbeatUsage() }
156		return fs
157	}
158	
159	func cmdSubmit(args []string) {
160		fs := newFlagSet("heartbeat submit")
161		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
162		receiveStr := fs.String("receive-time", "", "receive time (RFC3339); default: now")
163		if err := fs.Parse(args); err != nil {
164			if err == flag.ErrHelp {
165				os.Exit(0)
166			}
167			os.Exit(2)
168		}
169		if fs.NArg() != 0 {
170			die("submit takes no positional arguments; heartbeats are read from stdin")
171		}
172	
173		receiveTime := parseTimeFlag(*receiveStr, "--receive-time")
174	
175		data, err := io.ReadAll(os.Stdin)
176		if err != nil {
177			die("cannot read stdin: %v", err)
178		}
179		records, err := edgefleet.ParseHeartbeats(data, receiveTime)
180		if err != nil {
181			die("invalid input: %v", err)
182		}
183	
184		store, err := edgefleet.OpenStore(*dataDir)
185		if err != nil {
186			die("%v", err)
187		}
188		newCount, dupCount, err := store.Submit(records, receiveTime)
189		if err != nil {
190			die("%v", err)
191		}
192		fmt.Printf("submitted: new=%d duplicate=%d\n", newCount, dupCount)
193	}
194	
195	func cmdHealth(args []string) {
196		fs := newFlagSet("heartbeat health")
197		dataDir := fs.String("data-dir", defaultDataDir(), "data directory")
198		node := fs.String("node", "", "node id (required)")
199		atStr := fs.String("at", "", "query time (RFC3339); default: now")
200		expectedVersion := fs.String("expected-version", "", "expected version (required)")
