18	// simulating an operator restoring the wrong node's backup.
19	func copyFileBytes(t *testing.T, store *Store, dst, src string) {
20		t.Helper()
21		data, err := os.ReadFile(store.nodePath(src))
22		if err != nil {
23			t.Fatalf("test setup: read source file: %v", err)
24		}
25		if err := os.WriteFile(store.nodePath(dst), data, 0o644); err != nil {
26			t.Fatalf("test setup: plant copied file: %v", err)
27		}
28	}
29	
30	func TestCopiedNodeFileIsRefusedAsCorrupt(t *testing.T) {
31		dir := t.TempDir()
32		store, err := OpenStore(dir)
33		if err != nil {
34			t.Fatal(err)
35		}
36		receive := testBase
37		if _, _, err := store.Submit([]Heartbeat{
38			hb("乙", 1, receive.Add(-time.Minute), "1.0", 100, 0),
39			hb("乙", 2, receive.Add(-time.Second), "1.0", 101, 3),
40		}, receive); err != nil {
41			t.Fatal(err)
42		}
43		copyFileBytes(t, store, "甲", "乙")
44	
45		path := store.nodePath("甲")
46		check := func(name string, err error) {
47			t.Helper()
48			if err == nil || !IsCorrupt(err) {
49				t.Fatalf("%s must refuse the copied file as corruption, got %v", name, err)
50			}
51			msg := err.Error()
52			for _, want := range []string{path, "record 1", `"甲"`, `"乙"`} {
53				if !strings.Contains(msg, want) {
54					t.Errorf("%s error must contain %s: %v", name, want, err)
55				}
56			}
57		}
58	
59		_, err = store.Health("甲", receive, "1.0", 5)
60		check("health", err)
61		_, err = store.HealthSince("甲", receive, "1.0", 5, 1)
62		check("health with baseline", err)
63		_, err = store.History("甲")
64		check("history", err)
65	
66		// The real owner's data is untouched and still queryable.
67		r, err := store.Health("乙", receive, "1.0", 5)
68		if err != nil {
69			t.Fatalf("the copied-from node must stay queryable: %v", err)
70		}
71		if r.Seq != 2 || r.Height != 101 || r.Missed != 3 {
72			t.Errorf("source node telemetry misread: %+v", r)
73		}
74		hist, err := store.History("乙")
75		if err != nil || len(hist) != 2 {
76			t.Errorf("source node history broken: len=%d err=%v", len(hist), err)
77		}
78	}
