102			// missed-since query might use.
103			{"foreign middle record", []Heartbeat{
104				hb("n1", 1, at(1), "1.0", 10, 0),
105				hb("n2", 2, at(2), "1.0", 11, 0),
106				hb("n1", 3, at(3), "1.0", 12, 1),
107			}, "record 2"},
