		h.Version == o.Version &&
		h.Height == o.Height &&
		h.Missed == o.Missed &&
		h.CollectedAt.Equal(o.CollectedAt)
}

// heartbeatIdentity identifies one record independently of where it comes
// from: the node id and seq together. Different nodes sharing a seq, or the
// same node using different seqs, are different identities. Both components
// are compared as their exact values — node ids are never trimmed, cased or
// merged. Only batch/history classification uses it; Heartbeat.Equal stays the
// single full-content comparison.
type heartbeatIdentity struct {
	NodeID string
	Seq    int64
}

func identityOf(h Heartbeat) heartbeatIdentity {
	return heartbeatIdentity{NodeID: h.NodeID, Seq: h.Seq}
}

// ConflictError means two heartbeats carry the same identity (node id and
// seq) but differ in content — version, height, cumulative missed count or
// collection instant. It is returned whether the conflict is between two
// records of one submitted batch or between a submitted record and stored
// history; InBatch reports which. A conflict always fails the whole batch and
// never overwrites either record.
type ConflictError struct {
	NodeID  string
	Seq     int64
	InBatch bool
}

func (e *ConflictError) Error() string {
	if e.InBatch {
		return fmt.Sprintf("conflicting records for node %q seq %d in batch: content differs", e.NodeID, e.Seq)
	}
	return fmt.Sprintf("conflicting record for node %q seq %d: content differs from stored record", e.NodeID, e.Seq)
}

// IsConflict reports whether err is (or wraps) a ConflictError.
func IsConflict(err error) bool {
	var ce *ConflictError
	return errors.As(err, &ce)
}

// mergeHeartbeats classifies one submitted batch against the already saved
// history using a single, source-independent rule. Each input record is
// examined in order and handled by exactly one classification:
//
//   - a record whose identity is seen for the first time (in the batch or in
//     history) is new: it is merged into the per-node history;
//   - a later occurrence whose content Equal()s the first one is a duplicate,
//     counted by occurrence, whether the first occurrence was earlier in the
//     same batch or in stored history;
//   - any occurrence whose content differs from the record already seen under
//     that identity is a conflict and rejects the whole merge.
//
// history holds the currently saved records, grouped by node id; it must not
// contain two records of the same identity. It is not modified: the returned
// map owns all slices it contains. Its records are copied into the result so
// callers may keep both. Every node's result stays ascending by seq, with
// gaps preserved; inserting a smaller late seq therefore never displaces the
// max-seq record health queries use.
func mergeHeartbeats(batch []Heartbeat, history map[string][]Heartbeat) (merged map[string][]Heartbeat, newCount, dupCount int, err error) {
	merged = make(map[string][]Heartbeat, len(history)+1)
	for nodeID, records := range history {
		merged[nodeID] = append([]Heartbeat(nil), records...)
	}

	// seen is the one place the "already known under this identity" decision
	// lives. Each identity maps to the first record carrying it — first within
	// the batch, else the saved record. The same Equal comparison therefore
	// covers intra-batch and against-history occurrences.
	seen := make(map[heartbeatIdentity]Heartbeat, len(batch))
	for _, r := range batch {
		id := identityOf(r)
		if first, ok := seen[id]; ok {
			if !first.Equal(r) {
				return nil, 0, 0, &ConflictError{NodeID: r.NodeID, Seq: r.Seq, InBatch: true}
			}
			dupCount++
			continue
		}

		records := merged[r.NodeID]
		found := -1
		for i, e := range records {
			if e.Seq == r.Seq {
				found = i
				break
			}
		}
		if found >= 0 {
			// History never carries the same identity twice; remember its
			// content so further occurrences in this batch are judged against
			// the exact same rule as batch-internal repeats.
			seen[id] = records[found]
			if !records[found].Equal(r) {
				return nil, 0, 0, &ConflictError{NodeID: r.NodeID, Seq: r.Seq, InBatch: false}
			}
			dupCount++
			continue
		}

		seen[id] = r
		records = append(records, r)
		sort.Slice(records, func(i, j int) bool { return records[i].Seq < records[j].Seq })
		merged[r.NodeID] = records
		newCount++
	}
	return merged, newCount, dupCount, nil
}

