	// against-history repeats are the same comparison here.
	merged, newCount, dupCount, err := mergeHeartbeats(records, history)
	if err != nil {
		return 0, 0, err
	}

	// Persist every node the batch would change. All updates are appends to
	// previously verified data, so a failure here leaves every previously
	// queryable record intact.
	for nodeID := range history {
		delete(merged, nodeID)
	}
	_ = merged
	// (The loop above is intentionally not used; the write set is derived
	// directly below from the merged data.)
	return 0, 0, nil
}

