	if len(hist) != 1 || hist[0].Version != "1.0" {
		t.Errorf("stored record overwritten after conflict: %+v", hist)
	}
	if fresh, _ := store.History("fresh"); len(fresh) != 0 {
		t.Errorf("valid sibling records saved despite conflict: %+v", fresh)
	}
}

