diff --git a/edgefleet/heartbeat.go b/edgefleet/heartbeat.go
index efec479..75ba9f5 100644
--- a/edgefleet/heartbeat.go
+++ b/edgefleet/heartbeat.go
@@ -3,7 +3,9 @@ package edgefleet
 import (
 	"bytes"
 	"encoding/json"
+	"errors"
 	"fmt"
+	"sort"
 	"time"
 )

@@ -70,6 +72,108 @@ func (h Heartbeat) Equal(o Heartbeat) bool {
 		h.CollectedAt.Equal(o.CollectedAt)
 }

+// heartbeatIdentity identifies one record independently of where it comes
+// from: the node id and seq together. Different nodes sharing a seq, or the
+// same node using different seqs, are different identities. Both components
+// are compared as their exact values — node ids are never trimmed, cased or
+// merged. Only batch/history classification uses it; Heartbeat.Equal stays the
+// single full-content comparison.
+type heartbeatIdentity struct {
+	NodeID string
+	Seq    int64
+}
+
+func identityOf(h Heartbeat) heartbeatIdentity {
+	return heartbeatIdentity{NodeID: h.NodeID, Seq: h.Seq}
+}
+
+// ConflictError means two heartbeats carry the same identity (node id and
+// seq) but differ in content — version, height, cumulative missed count or
+// collection instant. It is returned whether the conflict is between two
+// records of one submitted batch or between a submitted record and stored
+// history; InBatch reports which. A conflict always fails the whole batch and
+// never overwrites either record.
+type ConflictError struct {
+	NodeID  string
+	Seq     int64
+	InBatch bool
+}
+
+func (e *ConflictError) Error() string {
+	if e.InBatch {
+		return fmt.Sprintf("conflicting records for node %q seq %d in batch: content differs", e.NodeID, e.Seq)
+	}
+	return fmt.Sprintf("conflicting record for node %q seq %d: content differs from stored record", e.NodeID, e.Seq)
+}
+
+// IsConflict reports whether err is (or wraps) a ConflictError.
+func IsConflict(err error) bool {
+	var ce *ConflictError
+	return errors.As(err, &ce)
+}
+
+// mergeHeartbeats classifies one submitted batch against the already saved
+// history with a single source-independent rule. Each input record is
+// examined in order against one table of records already known under the same
+// identity:
+//
+//   - the first occurrence of an identity is new and merged into the node's
+//     history;
+//   - every later occurrence whose content Equal()s the first one is a
+//     duplicate, counted per occurrence — it makes no difference whether the
+//     first occurrence was an earlier record of the same batch or a stored
+//     one;
+//   - any occurrence whose content differs from the record established under
+//     that identity is a conflict and rejects the whole merge. The conflict is
+//     reported as in-batch when the batch itself already supplied the
+//     differing record, otherwise as contradicting stored history.
+//
+// history holds the currently saved records grouped by node id and is assumed
+// unique per identity (the store verifies that invariant on load). It is read
+// only: its records are copied into the returned map, which owns all its
+// slices. Every node's result stays ascending by seq with gaps preserved, so
+// inserting a late, smaller seq never displaces the max-seq record health
+// queries use.
+func mergeHeartbeats(batch []Heartbeat, history map[string][]Heartbeat) (merged map[string][]Heartbeat, newCount, dupCount int, err error) {
+	merged = make(map[string][]Heartbeat, len(history)+1)
+	// known is the single table the "same identity, same content?" decision is
+	// made against. Seeding it from history is what lets batch-internal
+	// repeats and history repeats run through the identical comparison below.
+	known := make(map[heartbeatIdentity]Heartbeat, len(batch))
+	for nodeID, records := range history {
+		merged[nodeID] = append([]Heartbeat(nil), records...)
+		for _, e := range records {
+			known[identityOf(e)] = e
+		}
+	}
+	// inBatch marks identities the current batch itself has supplied an
+	// occurrence of, so a later differing occurrence is attributed to the
+	// batch rather than to stored history.
+	inBatch := make(map[heartbeatIdentity]bool, len(batch))
+
+	for _, r := range batch {
+		id := identityOf(r)
+		if first, ok := known[id]; ok {
+			if !first.Equal(r) {
+				return nil, 0, 0, &ConflictError{NodeID: r.NodeID, Seq: r.Seq, InBatch: inBatch[id]}
+			}
+			inBatch[id] = true
+			dupCount++
+			continue
+		}
+		known[id] = r
+		inBatch[id] = true
+		merged[r.NodeID] = append(merged[r.NodeID], r)
+		newCount++
+	}
+
+	for nodeID, records := range merged {
+		sort.Slice(records, func(i, j int) bool { return records[i].Seq < records[j].Seq })
+		merged[nodeID] = records
+	}
+	return merged, newCount, dupCount, nil
+}
+
 // ParseHeartbeats parses a JSON array of heartbeat objects. Every field must
 // be explicitly provided; missing or unknown fields are rejected with a
 // specific reason.

