80	// single full-content comparison.
81	type heartbeatIdentity struct {
82		NodeID string
83		Seq    int64
84	}
85	
86	func identityOf(h Heartbeat) heartbeatIdentity {
87		return heartbeatIdentity{NodeID: h.NodeID, Seq: h.Seq}
88	}
89	
90	// ConflictError means two heartbeats carry the same identity (node id and
91	// seq) but differ in content — version, height, cumulative missed count or
92	// collection instant. It is returned whether the conflict is between two
93	// records of one submitted batch or between a submitted record and stored
94	// history; InBatch reports which. A conflict always fails the whole batch and
95	// never overwrites either record.
96	type ConflictError struct {
97		NodeID  string
98		Seq     int64
99		InBatch bool
100	}
101	
102	func (e *ConflictError) Error() string {
103		if e.InBatch {
104			return fmt.Sprintf("conflicting records for node %q seq %d in batch: content differs", e.NodeID, e.Seq)
105		}
106		return fmt.Sprintf("conflicting record for node %q seq %d: content differs from stored record", e.NodeID, e.Seq)
107	}
108	
109	// IsConflict reports whether err is (or wraps) a ConflictError.
110	func IsConflict(err error) bool {
111		var ce *ConflictError
112		return errors.As(err, &ce)
113	}
114	
115	// foldedBatch is one batch reduced to a single record per identity, in first
116	// appearance order. dupCount counts the extra occurrences removed while
117	// folding (batch-internal duplicates).
118	type foldedBatch struct {
119		first map[heartbeatIdentity]Heartbeat
120		order []heartbeatIdentity
121		dup   int
122	}
123	
124	// foldBatch applies the duplicate/conflict rule within one batch. It is
125	// phase 1 of mergeHeartbeats and deliberately needs no stored data, so a
126	// batch that contradicts itself is rejected on those grounds before any
127	// history file is consulted — matching the submit order where an in-batch
128	// conflict takes precedence over an unrelated node's corrupt history.
129	func foldBatch(batch []Heartbeat) (foldedBatch, error) {
130		fb := foldedBatch{first: make(map[heartbeatIdentity]Heartbeat, len(batch))}
131		for _, r := range batch {
132			id := identityOf(r)
133			if established, ok := fb.first[id]; ok {
134				if !established.Equal(r) {
135					return foldedBatch{}, &ConflictError{NodeID: r.NodeID, Seq: r.Seq, InBatch: true}
136				}
137				fb.dup++
138				continue
139			}
140			fb.first[id] = r
141			fb.order = append(fb.order, id)
142		}
143		return fb, nil
144	}
