146	// mergeFolded applies the duplicate/conflict rule between a folded batch and
147	// saved history — phase 2 of mergeHeartbeats. The identity lookup and the
148	// Equal comparison are the same primitives foldBatch uses, so intra-batch and
149	// against-history judgements can never drift apart.
150	//
151	// history holds the currently saved records grouped by node id and is assumed
152	// unique per identity (the store verifies that invariant on load). It is read
153	// only: its records are copied into the returned map, which owns all its
154	// slices. Every node's result stays ascending by seq with gaps preserved, so
155	// inserting a late, smaller seq never displaces the max-seq record health
156	// queries use.
157	func mergeFolded(fb foldedBatch, history map[string][]Heartbeat) (merged map[string][]Heartbeat, newCount, dupCount int, err error) {
158		merged = make(map[string][]Heartbeat, len(history)+1)
159		known := make(map[heartbeatIdentity]Heartbeat, len(fb.order))
160		for nodeID, records := range history {
161			merged[nodeID] = append([]Heartbeat(nil), records...)
162			for _, e := range records {
